START TRANSACTION;
CREATE TABLE elemental_enhancement_grades (
 grade_code VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 grade_display_name VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
 grade_order INT UNSIGNED NOT NULL,names_json JSON NOT NULL,success_rate DECIMAL(9,6) NOT NULL,drop_rate DECIMAL(9,6) NOT NULL,
 item_cost BIGINT UNSIGNED NOT NULL,point_cost DECIMAL(30,3) NOT NULL,max_level BIGINT UNSIGNED NOT NULL,
 battle_exp BIGINT UNSIGNED NOT NULL,battle_upgrade_exp BIGINT UNSIGNED NOT NULL,raid_exp BIGINT UNSIGNED NOT NULL,raid_upgrade_exp BIGINT UNSIGNED NOT NULL,
 castle_exp BIGINT UNSIGNED NOT NULL,castle_upgrade_exp BIGINT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,
 PRIMARY KEY(grade_code),UNIQUE KEY uq_elemental_enhancement_grade_display(grade_display_name),UNIQUE KEY uq_elemental_enhancement_grade_order(grade_order),
 CONSTRAINT chk_elemental_enhancement_success CHECK(success_rate>=0 AND success_rate<=1),
 CONSTRAINT chk_elemental_enhancement_drop CHECK(drop_rate>=0 AND drop_rate<=1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE grade_display_name=VALUES(grade_display_name),grade_order=VALUES(grade_order),names_json=VALUES(names_json),success_rate=VALUES(success_rate),drop_rate=VALUES(drop_rate),item_cost=VALUES(item_cost),point_cost=VALUES(point_cost),max_level=VALUES(max_level),battle_exp=VALUES(battle_exp),battle_upgrade_exp=VALUES(battle_upgrade_exp),raid_exp=VALUES(raid_exp),raid_upgrade_exp=VALUES(raid_upgrade_exp),castle_exp=VALUES(castle_exp),castle_upgrade_exp=VALUES(castle_upgrade_exp),active=1;
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),asset_type_code=VALUES(asset_type_code),stackable=1,active=1;
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),rules_json=VALUES(rules_json),active=1;
ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),version=VALUES(version);
ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=1;
COMMIT;